        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.path = os.path.join(self.tmp.name, "house.txt")
        self.write(SAMPLE)

    def write(self, text, path=None):
        with open(path or self.path, "w", encoding="utf-8", newline="") as fh:
            fh.write(text)
        self.assertEqual(run("export", self.path)[1],
                         'date,category,amount,note\n2024-03-01,a,2.00,\n2024-03-05,b,1.00,"""hi, there"""\n')
        self.assertEqual(run("export", self.path, "--format", "csv")[0], 0)

    def test_stdin(self):
        for cmd, expected in [(("balance",), "1557.50\n"), (("summary",), None), (("list",), None), (("export",), None)]:
            code, out, _ = run(*cmd, "-", stdin=SAMPLE)
            self.assertEqual(code, 0)
            self.assertTrue(out)
            if expected:
                self.assertEqual(out, expected)

    def test_stdin_bad_ledger(self):
        code, out, err = run("balance", "-", stdin="oops\n")
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 1", err)


