class UnencodableOutputTests(unittest.TestCase):
    """stdout cannot encode the note: no traceback, and ``add`` exit status matches the file."""

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.path = os.path.join(self.tmp.name, "c.txt")
        with open(self.path, "wb") as fh:
            fh.write("2024-03-01 food 1 caf\u00e9\n".encode("utf-8"))

    def _run(self, *argv, **env_extra):
        env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "src"), **env_extra)
        return subprocess.run([sys.executable, "-m", "pennywise"] + list(argv),
                              capture_output=True, env=env)

    def _assert_clean(self, proc):
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertNotIn(b"Traceback", proc.stderr)
        self.assertEqual(proc.stderr, b"")

    def test_list_ascii_stdout(self):
        proc = self._run("list", self.path, PYTHONIOENCODING="ascii")
        self._assert_clean(proc)
        self.assertEqual(proc.stdout, b"2024-03-01 food 1.00 caf\\xe9\n")

    def test_export_ascii_stdout(self):
        proc = self._run("export", self.path, PYTHONIOENCODING="ascii")
        self._assert_clean(proc)
        self.assertIn(b"caf\\xe9", proc.stdout)

    def test_summary_ascii_stdout_non_ascii_category(self):
        with open(self.path, "wb") as fh:
            fh.write("2024-03-01 caf\u00e9 1\n".encode("utf-8"))
        proc = self._run("summary", self.path, PYTHONIOENCODING="ascii")
        self._assert_clean(proc)

